INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N039-06','CN0028','S039-06','设计产排量与历史在线范围','表3.2-48/49、表注','全厂设计产能下产生454417.5m³/a、排放432155.2m³/a（含生活），原环评产能排放288753.9m³/a。历史在线COD100–200、氨氮20–30mg/L；报告采用200/30估算，不能当成实测均值。分股量按表抄取，表格空白去向不猜。','WEB_PRIMARY','公开正文或表格摘录，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N039-07','CN0028','S039-06','历史水系统边界','表3.2-48/49','精馏4483.05m³/a、气提163234.6m³/a、低氨处理380093.7m³/a（各处理阶段可能重叠）。石灰除硫酸根效率65%为报告假定；非运行实测。截图超时；与2026正常运行披露独立存储。','WEB_PRIMARY','公开正文或表格摘录，非原件归档','2026-11-28');
